package com.example.smartpantrymanager.adapter;
import android.view.*;import android.widget.*;import androidx.recyclerview.widget.RecyclerView;import com.example.smartpantrymanager.R;import com.example.smartpantrymanager.model.Recipe;import java.util.*;
public class RecipeAdapter extends RecyclerView.Adapter<RecipeAdapter.VH>{public interface Listener{void open(Recipe r);}private List<Recipe> data;private Listener listener;public RecipeAdapter(List<Recipe>d,Listener l){data=d;listener=l;}public VH onCreateViewHolder(ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_recipe,p,false));}public void onBindViewHolder(VH h,int i){Recipe r=data.get(i);h.name.setText(r.getName());h.ingredients.setText("Ingredients: "+r.getIngredients());h.itemView.setOnClickListener(v->listener.open(r));}public int getItemCount(){return data.size();}static class VH extends RecyclerView.ViewHolder{TextView name,ingredients;VH(View v){super(v);name=v.findViewById(R.id.recipeName);ingredients=v.findViewById(R.id.recipeIngredients);}}}
